package dev.hollow.character;

import dev.hollow.Hollow;
import dev.hollow.core.setting.EnumSetting;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.resources.Identifier;

/**
 * Character Studio outfits. Cosmetic only: drawn on the local player, never sent to servers.
 * Geometry and textures are generated by {@code tools/characters.py}.
 */
public enum Cosmetic implements EnumSetting.Displayable {
	NONE("None", "", 0xFF9D4EDD, 2.2F),
	PHARAOH("Pharaoh", "pharaoh", 0xFFE6B54A, 2.3F),
	WRAITH("Wraith", "wraith", 0xFF7B3FD0, 2.3F),
	HOLLOW_KNIGHT("Hollow Knight", "hollow_knight", 0xFFC9A0FF, 2.45F),
	GRIM_REAPER("Grim Reaper", "grim_reaper", 0xFFB57BFF, 2.4F),
	SHADOW_NINJA("Shadow Ninja", "shadow_ninja", 0xFFD0453F, 2.25F),
	FROST_WITCH("Frost Witch", "frost_witch", 0xFF8FDCFF, 3.0F),
	INFERNAL_DEMON("Infernal Demon", "infernal_demon", 0xFFFF7A2A, 2.5F),
	STAR_VOYAGER("Star Voyager", "star_voyager", 0xFFF0A040, 2.45F);

	private final String displayName;
	private final String asset;
	private final int accent;
	private final ModelLayerLocation layer;
	private final Identifier texture;
	private final float viewHeight;

	Cosmetic(String displayName, String asset, int accent, float viewHeight) {
		this.displayName = displayName;
		this.asset = asset;
		this.accent = accent;
		this.viewHeight = viewHeight;
		this.layer = asset.isEmpty() ? null
			: new ModelLayerLocation(Identifier.fromNamespaceAndPath(Hollow.MOD_ID, "cosmetic_" + asset), "main");
		this.texture = asset.isEmpty() ? null : Identifier.fromNamespaceAndPath(Hollow.MOD_ID, "textures/entity/cosmetics/" + asset + ".png");
	}

	@Override
	public String displayName() {
		return displayName;
	}

	/** Base name of this outfit's model and texture files. */
	public String asset() {
		return asset;
	}

	public int accent() {
		return accent;
	}

	/** Height in blocks from the feet to the top of the outfit, used to frame it in menus. */
	public float viewHeight() {
		return viewHeight;
	}

	/** Model layer of this outfit; null for {@link #NONE}. */
	public ModelLayerLocation layer() {
		return layer;
	}

	/** Texture of this outfit; null for {@link #NONE}. */
	public Identifier texture() {
		return texture;
	}
}
